package com.mohymods.kingdomsmp.gametest;
import java.util.*;
import com.mohymods.kingdomsmp.building.*;
import com.mohymods.kingdomsmp.economy.*;
import com.mohymods.kingdomsmp.profession.*;
import net.minecraft.core.*;
import net.minecraft.gametest.framework.GameTestHelper;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.item.*;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.storage.LevelResource;
import net.minecraft.world.phys.AABB;
/** Native random growth time is accelerated only in supplied private budding cells; no evidence injected. */
final class AmethystRuntime {
 static BlockPos bud(int n){return new BlockPos(80+n*3,16,-48);}
 static void run(GameTestHelper h)throws Exception{
  var level=h.getLevel();var server=level.getServer();server.tickRateManager().setTickRate(20);var mine=ConstructionService.store(server).projects().stream().filter(q->q.blueprint().toString().equals(Profession.MINER.buildingId())).findFirst().orElseThrow();var p=server.getPlayerList().getPlayer(mine.owner());h.assertTrue(p!=null,"Original paid Miner attends");server.getPlayerList().deop(p.getGameProfile());var track=CommerceService.store(server).professions(p.getUUID()).track(Profession.MINER);var data=AmethystSavedData.get(server);var pending=server.getWorldPath(LevelResource.ROOT).resolve("amethyst-native-partial.txt");
  if(track.completedQuestIds().contains(AmethystGrowth.QUEST)){h.assertTrue(track.xp()==1800&&track.completedQuestIds().size()==13&&data.evidence().count(p.getUUID())==32&&p.getInventory().countItem(Items.AMETHYST_SHARD)==0&&ConstructionService.structureIntact(level,mine),"Third JVM restores genuine32harvested/32consumed/13earned1800XP/original Mine-Doran");CommerceService.verifyReceipt(p);com.mojang.logging.LogUtils.getLogger().info("AMETHYST_RESTART_PASSED: actual full native growth/32shards harvested+permanently consumed/native receipt/13earned1800XP and original Mine-Doran restore");h.succeed();return;}
  h.assertTrue(track.xp()==1600&&track.completedQuestIds().size()==12,"Starts from genuine full Apprentice/four native Journeyman seams");for(int n=0;n<12;n++){var at=bud(n);level.getChunkAt(at);ClaimRuntimeTests.ftbUnclaim(level,at);ClaimRuntimeTests.opacUnclaim(level,at);ClaimRuntimeTests.ftbClaim(p,at);ClaimRuntimeTests.opacClaim(level,p.getUUID(),at);}
  if(java.nio.file.Files.exists(pending)){h.assertTrue(data.evidence().count(p.getUUID())==16&&p.getInventory().countItem(Items.AMETHYST_SHARD)==16,"Second JVM retains actual partial production/inventory");for(int n=4;n<8;n++){h.assertTrue(data.evidence().at(bud(n).above().asLong()).stage()==2,"Actual unfinished native bud stage persists");grow(h,p,n,4);harvest(h,p,n);}h.runAfterDelay(3,()->guard(h,()->{h.assertTrue(data.evidence().count(p.getUUID())==32&&p.getInventory().countItem(Items.AMETHYST_SHARD)==32,"All32real native shard outputs match physical inventory");CreateCraftRuntime.counter(p,mine);var quote=ProfessionService.review(p,"materials:"+AmethystGrowth.QUEST);p.getInventory().removeItem(p.getInventory().findSlotMatchingItem(new ItemStack(Items.AMETHYST_SHARD)),1);boolean stale=false;try{ProfessionService.confirm(p,quote.nonce());}catch(IllegalStateException expected){stale=true;}h.assertTrue(stale&&CommerceService.store(server).professions(p.getUUID()).track(Profession.MINER).xp()==1600,"Changed inventory refuses stale material award");p.getInventory().add(new ItemStack(Items.AMETHYST_SHARD));quote=ProfessionService.review(p,"materials:"+AmethystGrowth.QUEST);ProfessionService.confirm(p,quote.nonce());boolean replay=false;try{ProfessionService.review(p,"materials:"+AmethystGrowth.QUEST);}catch(IllegalStateException expected){replay=true;}h.assertTrue(replay&&p.getInventory().countItem(Items.AMETHYST_SHARD)==0&&CommerceService.store(server).professions(p.getUUID()).track(Profession.MINER).xp()==1800,"Native receipt consumes32physical shards and grants200XPonce");for(int n=0;n<8;n++)h.assertTrue(level.getBlockState(bud(n)).is(Blocks.BUDDING_AMETHYST),"Every original budding support is preserved");CommerceService.verifyReceipt(p);com.mojang.logging.LogUtils.getLogger().info("AMETHYST_NATIVE_PASSED: native random bud stages survive interruption, actual32harvested shard drops/native pickups, actual32permanent delivery/changed-inventory/replay refusals/13earned1800XP and original Mine-Doran; supplied private budding blocks/native random growth time only, no growth/count/XP/quest/rank injection");h.succeed();}));return;}
  for(int n=0;n<12;n++){var at=bud(n);h.assertTrue(level.getBlockState(at).isAir()&&level.getBlockState(at.above()).isAir(),"Private supplied budding test cell is empty, never overwrite terrain/structures");level.setBlock(at,Blocks.BUDDING_AMETHYST.defaultBlockState(),3);for(var direction:Direction.values())if(direction!=Direction.UP){var around=at.relative(direction);h.assertTrue(level.getBlockState(around).isAir(),"Private random-growth enclosure is empty");level.setBlock(around,Blocks.STONE.defaultBlockState(),3);}}
  level.setBlock(bud(10).above(),Blocks.AMETHYST_CLUSTER.defaultBlockState().setValue(AmethystClusterBlock.FACING,Direction.UP),3);harvest(h,p,10);for(var stack:p.getInventory().items)if(stack.is(Items.AMETHYST_SHARD))stack.setCount(0);
  // Corrupt optional data must not throw through actual native growth or successful item/tool transactions.
  level.getDataStorage().set("kingdomsmp_amethyst_v1",new net.minecraft.world.level.saveddata.SavedData(){public net.minecraft.nbt.CompoundTag save(net.minecraft.nbt.CompoundTag t,HolderLookup.Provider r){return t;}});try{grow(h,p,11,4);harvest(h,p,11);}finally{level.getDataStorage().set("kingdomsmp_amethyst_v1",data);data.setDirty();}for(var stack:p.getInventory().items)if(stack.is(Items.AMETHYST_SHARD))stack.setCount(0);
  for(int n=0;n<4;n++){grow(h,p,n,4);if(n==0)claims(h,p);harvest(h,p,n);}for(int n=4;n<8;n++)grow(h,p,n,2);h.runAfterDelay(3,()->guard(h,()->{h.assertTrue(data.evidence().count(p.getUUID())==16&&p.getInventory().countItem(Items.AMETHYST_SHARD)==16,"Only four genuine native grown clusters yield16tracked physical shards; placed/faulted mature stock cannot count");CreateCraftRuntime.counter(p,mine);p.getInventory().add(new ItemStack(Items.AMETHYST_SHARD,16));boolean refused=false;try{ProfessionService.review(p,"materials:"+AmethystGrowth.QUEST);}catch(IllegalStateException expected){refused=true;}h.assertTrue(refused,"Full stocked32shards cannot replace missing genuine native growth");p.getInventory().removeItem(p.getInventory().findSlotMatchingItem(new ItemStack(Items.AMETHYST_SHARD)),16);java.nio.file.Files.writeString(pending,"Actual partial native growth/16harvested shards; remaining4medium buds persist");com.mojang.logging.LogUtils.getLogger().info("AMETHYST_PENDING_PASSED: native mature growth/16genuine shards plus saved4medium buds; placed mature and corrupt optional evidence grant no proof, native growth/tool/drop transactions still succeed");h.succeed();}));
 }
 static void claims(GameTestHelper h,ServerPlayer p)throws Exception{var level=p.serverLevel();var at=bud(0).above();var guard=ClaimRuntimeTests.vanillaPlayer(level,UUID.nameUUIDFromBytes("AmethystClaimGuard".getBytes(java.nio.charset.StandardCharsets.UTF_8)),"CrystalGuard");BlacksmithRepairRuntime.near(p,at);p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.IRON_PICKAXE));ClaimRuntimeTests.ftbUnclaim(level,at);ClaimRuntimeTests.ftbClaim(guard,at);h.assertTrue(!p.gameMode.destroyBlock(at)&&AmethystSavedData.get(p.server).evidence().at(at.asLong()).stage()==4,"Current FTB denial retains actual mature growth without loot/credit");ClaimRuntimeTests.ftbUnclaim(level,at);ClaimRuntimeTests.ftbClaim(p,at);ClaimRuntimeTests.opacUnclaim(level,at);ClaimRuntimeTests.opacClaim(level,guard.getUUID(),at);h.assertTrue(!p.gameMode.destroyBlock(at)&&AmethystSavedData.get(p.server).evidence().at(at.asLong()).stage()==4,"Independent OPAC denial retains real cluster and growth");ClaimRuntimeTests.opacUnclaim(level,at);ClaimRuntimeTests.opacClaim(level,p.getUUID(),at);}
 static void grow(GameTestHelper h,ServerPlayer p,int n,int target){var level=p.serverLevel();var at=bud(n);for(int tries=0;tries<10000&&AmethystGrowth.stage(level.getBlockState(at.above()))<target;tries++)level.getBlockState(at).randomTick(level,at,level.random);h.assertTrue(AmethystGrowth.stage(level.getBlockState(at.above()))==target,"Actual native random growth reaches stage "+target);}
 static void harvest(GameTestHelper h,ServerPlayer p,int n){var at=bud(n).above();BlacksmithRepairRuntime.near(p,at);p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.IRON_PICKAXE));h.assertTrue(p.gameMode.destroyBlock(at)&&p.getMainHandItem().getDamageValue()==1,"Actual native cluster removal/real tool wear");for(var entity:p.serverLevel().getEntitiesOfClass(ItemEntity.class,new AABB(at).inflate(2)))if(entity.getItem().is(Items.AMETHYST_SHARD)){entity.setNoPickUpDelay();entity.playerTouch(p);}}
 interface Action{void run()throws Exception;}static void guard(GameTestHelper h,Action action){try{action.run();}catch(Exception error){h.fail(error.toString());}}
}
